window.products.push({"id":871258,"name":"MSC International Joie Acrylic Wine Aerator, Turquoise, 1-Pack","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/214Yo27dLdL._AC_.jpg","description":"\"Some wines are expensive and some barely cost a few bucks. The important thing is choosing the one you want. At the beginning of the night, you need to let your wine properly breathe. You don’t want the wine to go to waste so you need the right tools to accomplish this blend of flavors. This Joie Wine Aerator helps you to keep your wine breathing, letting you store it safely in your ice bucket for your guests to continue to pour from. After you’re done pouring, this aerator keeps it from dripping and unnecessarily losing precious drops of your favorite vino. All you need to do is to push the aerator down into the neck firmly with the rubber grip. Add this to the rest of your entertaining accessories to prepare for the next dinner party. \"","images":["https://m.media-amazon.com/images/I/214Yo27dLdL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Joie","source_asin":"B01555KK72","category_path":"Home & Kitchen"},"sku":"BM-871258","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01555KK72","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01555KK72","price_pending":true,"merchant_ready":false});
